public void modifyRegistrationCollectors(TFMRegistrationCollectors _collectors)
{
    MapEnumerator               mEnum = _collectors.collectorMap().getEnumerator();
    TFMRegistrationCollector    col;
    super(_collectors);

    while (mEnum.moveNext())
    {
        col = mEnum.currentValue();
        col.parmDisableValueTransfer(true);
    }

}

public void modifyHeaderCollectors(TFMReferenceDataConfiguration _refConf)
{
    SetEnumerator               sEnum = _refConf.getCollectors().getEnumerator();
    TFMRegistrationCollector    col;
    super(_refConf);

    while (sEnum.moveNext())
    {
        col = sEnum.current();
        col.parmDisableValueTransfer(col.getEDT() == extendedTypeStr(itemId));
    }
}
